{
  "findings": [
    {
      "requirement_ids": [
        "R-05",
        "R-12"
      ],
      "criterion": "consistent",
      "severity": "critical",
      "title": "Противоречие в критерии приёмки для комиссии",
      "evidence": [
        {
          "quote": "Переводы за месяц 0 ₸ | Перевести 25 000 ₸ | Комиссия 0 ₸",
          "line": 57
        },
        {
          "quote": "Ф-3. Переводы до 20 000 ₸ в месяц выполняются без комиссии. Сверх лимита взимается комиссия 1%.",
          "line": 36
        }
      ],
      "problem": "В критерии приёмки указана комиссия 0 ₸ при переводе 25 000 ₸, хотя согласно Ф-3 бесплатный лимит составляет 20 000 ₸. Перевод 25 000 ₸ превышает лимит, поэтому комиссия не может быть нулевой.",
      "recommendation": "Скоректировать ожидаемый результат в таблице критериев приёмки с учётом комиссионного лимита.",
      "rewrite": "Переводы за месяц 0 ₸ | Перевести 25 000 ₸ | Комиссия 50 ₸"
    },
    {
      "requirement_ids": [
        "R-05"
      ],
      "criterion": "verifiable",
      "severity": "major",
      "title": "Неоднозначность расчёта комиссии при частичном превышении лимита",
      "evidence": [
        {
          "quote": "Ф-3. Переводы до 20 000 ₸ в месяц выполняются без комиссии. Сверх лимита взимается комиссия 1%.",
          "line": 36
        }
      ],
      "problem": "Формулировка «Сверх лимита взимается комиссия 1%» позволяет два толкования: комиссия 1% берется только от суммы превышения лимита (дельта) или от всей суммы операции, превысившей лимит. Это делает требование непроверяемым без уточнения формулы.",
      "recommendation": "Явно прописать порядок и формулу расчёта комиссии при превышении ежемесячного лимита.",
      "rewrite": "Ф-3. Переводы до 20 000 ₸ в месяц выполняются без комиссии. При превышении лимита комиссия 1% взимается только с суммы превышения (требует подтверждения)."
    },
    {
      "requirement_ids": [
        "R-06"
      ],
      "criterion": "verifiable",
      "severity": "major",
      "title": "Неопределён точный момент обнуления месячного лимита",
      "evidence": [
        {
          "quote": "Ф-5. Месячный лимит бесплатных переводов обнуляется в начале месяца.",
          "line": 37
        }
      ],
      "problem": "Термин «в начале месяца» не даёт точного времени и часового пояса (например, 00:00:00 UTC+5 1-го числа). Нельзя составить однозначный тест-кейс на сброс лимита на стыке месяцев.",
      "recommendation": "Указать точную дату, время и часовой пояс для процедуры обнуления лимита.",
      "rewrite": "Ф-5. Месячный лимит бесплатных переводов обнуляется первого числа каждого календарного месяца в 00:00:00 по времени г. Астана (UTC+5)."
    },
    {
      "requirement_ids": [
        "R-11",
        "R-12",
        "R-13"
      ],
      "criterion": "set_complete",
      "severity": "critical",
      "title": "Неполное покрытие требований критериями приёмки",
      "evidence": [
        {
          "quote": "Критерии приемки",
          "line": 52
        }
      ],
      "problem": "В критериях приёмки представлены только 3 сценария. Отсутствуют проверки верхней границы (500 000 ₸), превышения максимума (500 001 ₸), повторных вызовов (идемпотентности), статусов ошибок API и сброса лимита в новом месяце.",
      "recommendation": "Дополнить критерии приёмки проверками всех граничных условий и негативных сценариев.",
      "rewrite": ""
    },
    {
      "requirement_ids": [
        "R-24",
        "R-28"
      ],
      "criterion": "verifiable",
      "severity": "major",
      "title": "Не описан формат ответа API при ошибках",
      "evidence": [
        {
          "quote": "status | string | OK / ERROR | Результат перевода",
          "line": 110
        }
      ],
      "problem": "Спецификация не содержит описания структурированного тела ответа при status=ERROR (отсутствуют поля кода ошибки и текстового сообщения), из-за чего невозможно проверить обработку ошибок на клиенте.",
      "recommendation": "Добавить спецификацию структуры ответа для статус-кодов 400, 401 и 409 с описанием полей errorCode и errorMessage.",
      "rewrite": ""
    }
  ],
  "suggested_tests": [
    {
      "requirement_ids": [
        "R-04"
      ],
      "title": "Перевод на минимально допустимую сумму 100 KZT",
      "preconditions": "Карта клиента активна, баланс 1 000 KZT, лимит за месяц 0 KZT",
      "action": "Отправить запрос на перевод 100 KZT",
      "expected": "Перевод успешно выполнен, комиссия 0 KZT",
      "gap": "В критериях приёмки отсутствует проверка нижней граничной суммы 100 KZT"
    },
    {
      "requirement_ids": [
        "R-04"
      ],
      "title": "Перевод на максимально допустимую сумму 500 000 KZT",
      "preconditions": "Баланс карты 600 000 KZT, лимит за месяц 0 KZT",
      "action": "Отправить запрос на перевод 500 000 KZT",
      "expected": "Перевод успешно выполнен, комиссия рассчитывается согласно Ф-3 (4 800 KZT)",
      "gap": "В критериях приёмки отсутствует проверка верхней граничной суммы 500 000 KZT"
    },
    {
      "requirement_ids": [
        "R-04"
      ],
      "title": "Попытка перевода суммы свыше максимального лимита 500 001 KZT",
      "preconditions": "Баланс карты 600 000 KZT",
      "action": "Отправить запрос на перевод 500 001 KZT",
      "expected": "Ошибка валидации параметра amount, операция не выполняется",
      "gap": "Отсутствует проверка превышения максимальной суммы перевода"
    },
    {
      "requirement_ids": [
        "R-05"
      ],
      "title": "Перевод на граничную сумму бесплатного лимита 20 000 KZT",
      "preconditions": "Накопленные переводы за текущий месяц 0 KZT",
      "action": "Отправить запрос на перевод 20 000 KZT",
      "expected": "Перевод выполняется успешно, комиссия 0 KZT",
      "gap": "В критериях приёмки отсутствует точная проверка границы 20 000 KZT"
    },
    {
      "requirement_ids": [
        "R-05"
      ],
      "title": "Перевод при превышении бесплатного лимита на 1 KZT (20 001 KZT)",
      "preconditions": "Накопленные переводы за текущий месяц 0 KZT",
      "action": "Отправить запрос на перевод 20 001 KZT",
      "expected": "Не определено требованиями: расчёт комиссии 1% с дельты 1 KZT или с полной суммы 20 001 KZT не однозначен в Ф-3",
      "gap": "Отсутствует критерий приёмки для первой операции с превышением лимита"
    },
    {
      "requirement_ids": [
        "R-06"
      ],
      "title": "Сброс накопленного лимита 1-го числа месяца",
      "preconditions": "Накопленная сумма переводов за прошлый месяц 50 000 KZT. Наступило 1-е число нового месяца 00:00:01 (UTC+5)",
      "action": "Отправить запрос на перевод 10 000 KZT",
      "expected": "Комиссия 0 KZT, так как лимит обнулился",
      "gap": "Отсутствует проверка сброса ежемесячного лимита в начале месяца"
    },
    {
      "requirement_ids": [
        "R-07",
        "R-23"
      ],
      "title": "Повторная отправка запроса перевода (защита от двойного списания)",
      "preconditions": "Первый запрос на перевод успешно отправлен",
      "action": "Отправить повторный идентичный запрос перевода",
      "expected": "Двойное списание не происходит, возвращается статус 409",
      "gap": "В критериях приёмки нет сценария повторной отправки запроса"
    },
    {
      "requirement_ids": [
        "R-29"
      ],
      "title": "Отправка запроса без авторизационного токена",
      "preconditions": "Токен авторизации отсутствует в заголовке",
      "action": "Отправить GET /transfers/create",
      "expected": "Возвращается HTTP status 401 Unauthorized",
      "gap": "В критериях приёмки отсутствуют негативные проверки авторизации"
    }
  ],
  "acceptance_checks": [
    {
      "acceptance_quote": "Переводы за месяц 0 ₸ | Перевести 15 000 ₸ | Комиссия 0 ₸",
      "acceptance_line": 56,
      "row_facts": "Исходные условия: накопленная сумма переводов за месяц равна 0 KZT. Действие: выполнение перевода на сумму 15 000 KZT.",
      "requirement_ids": [
        "R-05"
      ],
      "requirement_quote": "Ф-3. Переводы до 20 000 ₸ в месяц выполняются без комиссии. Сверх лимита взимается комиссия 1%.",
      "requirement_line": 36,
      "expected_by_requirements": "Комиссия 0 KZT, так как сумма 15 000 KZT находится в пределах бесплатного лимита 20 000 KZT.",
      "stated_expected": "Комиссия 0 ₸",
      "verdict": "совпадает",
      "explanation": "Результат совпадает с требованиями Ф-3: сумма перевода 15 000 KZT не превышает лимит 20 000 KZT."
    },
    {
      "acceptance_quote": "Переводы за месяц 0 ₸ | Перевести 25 000 ₸ | Комиссия 0 ₸",
      "acceptance_line": 57,
      "row_facts": "Исходные условия: накопленная сумма переводов за месяц равна 0 KZT. Действие: выполнение перевода на сумму 25 000 KZT.",
      "requirement_ids": [
        "R-05"
      ],
      "requirement_quote": "Ф-3. Переводы до 20 000 ₸ в месяц выполняются без комиссии. Сверх лимита взимается комиссия 1%.",
      "requirement_line": 36,
      "expected_by_requirements": "Комиссия 50 KZT (1% от суммы превышения лимита 5 000 KZT, 25 000 - 20 000 = 5 000 KZT).",
      "stated_expected": "Комиссия 0 ₸",
      "verdict": "противоречит",
      "explanation": "В критерии приёмки указана комиссия 0 ₸, но согласно Ф-3 бесплатный лимит равен 20 000 ₸. На сумму превышения 5 000 ₸ должна рассчитываться комиссия 1% (50 ₸)."
    },
    {
      "acceptance_quote": "Баланс карты 1 000 ₸ | Перевести 99 ₸ | Ошибка «Минимальная сумма 100 ₸»",
      "acceptance_line": 58,
      "row_facts": "Исходные условия: баланс карты составляет 1 000 KZT. Действие: выполнение перевода на сумму 99 KZT.",
      "requirement_ids": [
        "R-04"
      ],
      "requirement_quote": "Ф-2. Сумма одного перевода — от 100 до 500 000 ₸.",
      "requirement_line": 35,
      "expected_by_requirements": "Отказ в проведении операции, так как минимальная сумма перевода равна 100 KZT.",
      "stated_expected": "Ошибка «Минимальная сумма 100 ₸»",
      "verdict": "совпадает",
      "explanation": "Результат совпадает: сумма 99 KZT меньше минимального порога 100 KZT, установленного требованием Ф-2."
    }
  ]
}
